import React from 'react';
import { Link } from 'react-router-dom';
function About(){
    return(
        <>
                <div className="bg-red-600  flex justify-center items-center flex-col space-y-6">

                     <img src="profile.avif"  className="h-48 w-48 object-cover"/>
                     <span className="font-extrabold text-white text-6xl text-center">ABOUT ME </span>
                    <p className="text-white text-center mt-4">I'm a communication designer who thrives on creativity and connection. I see design as a way to tell stories and bring people together. When I'm not crafting visual magic, you'll find me experimenting with video games, making potions in my room, or planning my next travel adventure. I believe that great design starts with a spark of curiosity and a dash of fun, and I can't wait to share explore and learn more everyday!</p>

                    <button>LinkedIn </button>
                </div>


        </>
    )
}
export default About;
